	@Override
	public final boolean hasNext() {
		if (isClosed()) {
			return false;
		}

		return lookAhead() != null;
	}

	@Override
	public final Statement next() {
		if (isClosed()) {
			throw new NoSuchElementException("The iteration has been closed.");
		}
		Statement result = lookAhead();

		if (result != null) {
			nextElement = null;
			return result;
		} else {
			throw new NoSuchElementException();
		}
	}

	/**
	 * Fetches the next element if it hasn't been fetched yet and stores it in {@link #nextElement}.
	 *
	 * @return The next element, or null if there are no more results.
	 */
	private Statement lookAhead() {
		checkCancellation();
		if (nextElement == null) {
			try {
				nextElement = getNextElement();
				checkCancellation();
			} catch (RuntimeException | Error failure) {
				KernelRuntime.closeCursor(this, failure);
				throw failure;
			}

			if (nextElement == null) {
				close();
			}
		}
		return nextElement;
	}

